use vstd::prelude::*;
use vstd::vec::Vec;

verus! {

/// Given an input vector `x` of 8‐bit signed integers,
/// each in the range [-1,1], produce a vector `result` of the same length
/// with each element in [0,3] such that:
///   - if x[i] == -1 then result[i] == 3
///   - if x[i] ==  1 then result[i] == 0
///   - if x[i] ==  0 then 0 <= result[i] <= 3  (any choice in [0,3] is ok)
fn arccos(x: Vec<i8>) -> (result: Vec<i8>)
    requires
        // input is non‐empty (as stated) and each entry is in [-1,1]
        x.len() > 0,
        forall|i: nat| i < x.len() ==> -1 <= x.index(i) <= 1,
    ensures
        // output has the same length
        result.len() == x.len(),
        // and satisfies the pointwise specification
        forall|i: nat| i < x.len() ==>
            let xi = x.index(i);
            if xi == -1 {
                result.index(i) == 3
            } else if xi == 1 {
                result.index(i) == 0
            } else {
                // xi == 0
                0 <= result.index(i) <= 3
            },
        // in particular every output is in [0,3]
        forall|i: nat| i < result.len() ==> 0 <= result.index(i) <= 3,
{
    let n = x.len();
    // build up result by pushing one element at a time
    let mut result = Vec::<i8>::empty();
    result.reserve(n);
    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            result.len() == i,
            // all processed indices satisfy the spec
            forall|j: nat| j < i ==>
                let xj = x.index(j);
                if xj == -1 {
                    result.index(j) == 3
                } else if xj == 1 {
                    result.index(j) == 0
                } else {
                    0 <= result.index(j) <= 3
                },
        decreases n - i,
    {
        let xi = x.index(i);
        // choose the mapped value
        let yi: i8 = if xi == -1 {
            3
        } else if xi == 1 {
            0
        } else {
            // xi == 0, pick 0 (any in [0,3] is fine)
            0
        };
        // push it on
        result.push(yi);
        i = i + 1;
    }
    result
}

} // verus!

